const startItem = $('Start').first().json || {};
const triggerData = startItem.body || startItem.payload || startItem || {};
const configs = startItem.configs || triggerData.configs || {};
const loja = $input.item.json || {};
const evoConfig = loja.config_json?.evolutionapi || {};

const defaultEvolutionKey = (configs.evolution_api_key || '').trim();
const defaultEvolutionUrl = (configs.evolution_api_url || 'https://evolution.rogeriomaciel.com.br').replace(/\/+$/, '');

let instanceName = (evoConfig.instanceName || '').trim();
if (!instanceName || instanceName === 'loja-undefined' || instanceName === 'loja-null') {
  instanceName = `loja-${loja.id}`;
}

const apikey = (evoConfig.apikey || '').trim() || defaultEvolutionKey;
let apiUrl = (evoConfig.apiUrl || '').trim().replace(/\/+$/, '');
if (!apiUrl || apiUrl.includes('api.evolution.com.br')) {
  apiUrl = defaultEvolutionUrl;
}

const evolutionAction = (triggerData.evolutionAction || 'STATUS').toUpperCase();

if (!apiUrl || !instanceName) {
  return {
    json: {
      hasError: true,
      error: 'Instância ou URL da Evolution API não configurada para esta loja.'
    }
  };
}

let url = '';
let method = 'GET';

if (evolutionAction === 'STATUS') {
  url = `${apiUrl}/instance/fetchInstances?instanceName=${instanceName}`;
} else if (evolutionAction === 'CONNECT') {
  url = `${apiUrl}/instance/connect/${instanceName}`;
} else if (evolutionAction === 'LOGOUT') {
  url = `${apiUrl}/instance/logout/${instanceName}`;
  method = 'DELETE';
} else if (evolutionAction === 'RESTART') {
  url = `${apiUrl}/instance/restart/${instanceName}`;
  method = 'POST';
} else {
  url = `${apiUrl}/instance/fetchInstances?instanceName=${instanceName}`;
}

return {
  json: {
    hasError: false,
    evolutionAction,
    url,
    method,
    apikey,
    instanceName,
    loja_id: loja.id
  }
};

const res = $input.item.json;
const item = Array.isArray(res) ? (res[0] || {}) : res;
const loja = $('Buscar Loja').first().json || {};

const rawOwner = item?.ownerJid || item?.owner || item?.number || item?.instance?.ownerJid || item?.instance?.owner || item?.instance?.number || item?.profile?.id || '';
const cleanPhone = rawOwner ? String(rawOwner).split('@')[0].split(':')[0].replace(/\D/g, '') : '';
const formattedPhone = cleanPhone ? (cleanPhone.startsWith('55') ? cleanPhone : ('55' + cleanPhone)) : '';

// Só tenta atualizar o banco se a loja não tiver telefone cadastrado ainda
const currentPhone = loja.whatsapp_loja || '';
const shouldUpdate = Boolean(formattedPhone && loja.id && !currentPhone);

return {
  json: {
    ok: true,
    data: item,
    ownerPhone: formattedPhone,
    number: formattedPhone,
    loja_id: loja.id,
    shouldUpdate
  }
};

const original = $('Formatar Resposta').first().json;
return {
  json: {
    ok: true,
    data: original.data,
    ownerPhone: original.ownerPhone,
    number: original.ownerPhone
  }
};
